// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 id) public {
        vm.assume(!c.isOperation(id));
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));
        assertTrue(!success);
    }
}

